"""Booktabs tables for a paper draft. UTF-8, ready to \\input."""

from __future__ import annotations

from pathlib import Path

import pandas as pd


def _cell(value) -> str:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return "--"
    if isinstance(value, float):
        return f"{value:.2f}"
    return str(value).replace("&", "\\&").replace("%", "\\%").replace("_", "\\_")


def write_latex(summary: pd.DataFrame, car_path: Path, dest: Path) -> None:
    part = summary[summary["window_months"] == 6].copy()
    lines = [
        "% Auto-generated by build.py. Do not edit by hand.",
        "\\begin{table}[ht]",
        "\\centering",
        "\\caption{Six-month windows after each hand-dated event}",
        "\\begin{tabular}{lrrrr}",
        "\\toprule",
        "Event & Gold & Brent & CSI 300 & Haven \\\\",
        "\\midrule",
    ]
    for row in part.itertuples():
        name = _cell(row.event_name)
        lines.append(
            f"{name} & {_cell(row.gold_cum)} & {_cell(row.brent_cum)} & {_cell(row.csi_cum)} & {_cell(row.haven_after)} \\\\"
        )
    lines.extend(
        [
            "\\bottomrule",
            "\\end{tabular}",
            "\\end{table}",
            "",
        ]
    )
    if car_path.exists():
        car = pd.read_csv(car_path)
        gold = car[(car["asset"] == "gold") & (car["window"] == "m1_p5")]
        lines.extend(
            [
                "\\begin{table}[ht]",
                "\\centering",
                "\\caption{Gold mean-adjusted CAR over trading days $[-1,+5]$}",
                "\\begin{tabular}{lrrr}",
                "\\toprule",
                "Event & CAR & t & BH q \\\\",
                "\\midrule",
            ]
        )
        for row in gold.itertuples():
            lines.append(
                f"{_cell(row.event_id)} & {_cell(row.car)} & {_cell(row.t)} & {_cell(getattr(row, 'q', None))} \\\\"
            )
        lines.extend(["\\bottomrule", "\\end{tabular}", "\\end{table}", ""])
    dest.write_text("\n".join(lines), encoding="utf-8")
